<script setup lang="ts">
import { ref, onBeforeUnmount } from 'vue'
import { useAuthStore } from '@/stores/auth'
import { inventory, journal, action, exportSubject, type InventoryRecord, type JournalEntry } from './api'
const auth = useAuthStore()
const can = (p: string) => auth.hasExtensionPermission(`governance:${p}`)
const unit = ref(''), subject = ref(''), request = ref(''), reference = ref(''), kind = ref('access'), selected = ref(''), hold = ref(''), policySource = ref('case'), seconds = ref(''), expected = ref('1'), narrative = ref(''), reason = ref('')
const rows = ref<InventoryRecord[]>([]), entries = ref<JournalEntry[]>([]), busy = ref(false), error = ref(''), notice = ref(''), reviewed = ref(false)
const base = () => ({ unit_id: unit.value.trim(), subject_id: subject.value.trim(), request_id: request.value.trim() })
async function run(fn: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await fn() } catch (e: unknown) { rows.value = []; entries.value = []; const code = (e as {response?: {data?: {error?: {code?: string}}}}).response?.data?.error?.code; error.value = code === 'blocked_hold' ? 'An active legal hold blocks this change.' : code === 'blocked_retention_or_policy' ? 'Retention or an unapproved policy blocks deletion.' : code === 'approval_required' ? 'The deletion request requires approval first.' : code === 'conflict' ? 'This version changed. Refresh and review before trying again.' : 'The operation did not confirm success. Check current permissions and durable state before retrying.' } finally { busy.value = false; reviewed.value = false } }
async function load() { rows.value = await inventory(unit.value.trim()); if (request.value.trim()) entries.value = await journal(unit.value.trim(), request.value.trim()) }
async function execute(name: string, extra: Record<string, unknown> = {}) { await run(async () => { await action(name, { ...base(), ...extra }); await load(); notice.value = 'Saved. Review the actual inventory and journal states below.' }) }
async function discover() { await run(async () => { rows.value = await action<InventoryRecord[]>('discover', base()) ?? []; notice.value = 'Accessible objects discovered. External stores and retained minimal identifiers remain separate.' }) }
async function download() { await run(async () => { const data = await exportSubject(unit.value.trim(), subject.value.trim()); const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], {type: 'application/json'})); const link = document.createElement('a'); link.href = url; link.download = 'privacy-authorized-export.json'; link.click(); URL.revokeObjectURL(url); notice.value = 'Authorized export downloaded. Handle this copy under the approved retention and access policy.' }) }
onBeforeUnmount(() => { rows.value = []; entries.value = []; narrative.value = ''; reason.value = ''; subject.value = ''; reference.value = '' })
</script>
<template>
 <main class="governance-page"><header><h1>Record governance</h1><p>Discover authorized records, handle verified requests, review holds and apply governed changes to stored objects.</p></header>
 <p class="policy-note">Demonstration policies are provisional. A local SQL erasure receipt does not certify erasure of backups, worker files, carrier copies or downloaded exports.</p>
 <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="busy" role="status">Loading or saving…</p>
 <section><h2>Verified request scope</h2><label>Exact unit identifier<input v-model="unit" :disabled="busy" /></label><label>Subject employee ID or explicit document ID<input v-model="subject" :disabled="busy" /></label><label>Request identifier<input v-model="request" :disabled="busy" /></label><label>Verified authority reference (identifier only)<input v-model="reference" :disabled="busy" /></label><label>Request kind<select v-model="kind" :disabled="busy"><option>access</option><option>export</option><option>correct</option><option>delete</option></select></label>
 <button :disabled="busy || !unit" @click="run(load)">Refresh stored status</button><button v-if="can('inventory.write')" :disabled="busy || !unit || !subject" @click="discover">Discover actual objects</button><button v-if="can(`request.${kind}`)" :disabled="busy || !request || !reference || !subject || !unit" @click="execute('requests', {kind, reference})">Record verified request</button><button v-if="can('request.export')" :disabled="busy || !subject || !unit" @click="download">Download authorized export</button>
 </section>
 <section v-if="can('deletion.approve') || can('deletion.record')"><h2>Deletion review</h2><p>Discover the full accessible scope, obtain authority, check retention and holds, then approve the deletion request. Shared cases and documents require their source owner's review.</p><label>Expected request version<input v-model="expected" type="number" min="1" :disabled="busy" /></label><button v-if="can('deletion.approve')" :disabled="busy || !request" @click="execute('approve', {expected_version: Number(expected)})">Approve deletion request</button><button v-if="can('deletion.record')" :disabled="busy || !request" @click="execute('plan')">Refresh deletion plan</button><label><input v-model="reviewed" type="checkbox" :disabled="busy" />I reviewed this subject, authority, legal holds, retention and source-owner impact.</label><button v-if="can('deletion.record')" :disabled="busy || !request || !reviewed" @click="execute('erase')">Apply governed physical erasure</button></section>
 <section v-if="can('hold.manage')"><h2>Legal hold</h2><label>Hold identifier<input v-model="hold" :disabled="busy" /></label><label>Root lineage identifier<input v-model="selected" :disabled="busy" /></label><button :disabled="busy || !hold || !selected || !reference" @click="execute('hold', {hold_id: hold, lineage_id: selected, reference, active: true})">Apply hold</button><button :disabled="busy || !hold || !selected || !reference" @click="execute('hold', {hold_id: hold, lineage_id: selected, reference, active: false})">Release reviewed hold</button></section>
 <section v-if="can('policy.manage')"><h2>Retention rule</h2><p>No duration is approved automatically. Obtain the accountable owner's decision before configuring a production rule.</p><label>Source class<select v-model="policySource"><option v-for="s in ['case','knowledge','directory','conversation','report','ai','backup','provider','worker_file','audit','core','vector']" :key="s">{{ s }}</option></select></label><label>Approved minimum retention (seconds)<input v-model="seconds" type="number" min="0" :disabled="busy" /></label><button :disabled="busy || seconds === '' || !unit" @click="execute('rule', {source: policySource, minimum_retention_seconds: Number(seconds), approved: true})">Record approved rule</button></section>
 <section v-if="can('request.correct')"><h2>Correct current case narrative</h2><p>The recorded correction request must target this case's subject. An active hold blocks overwrite. Creation dimensions and historical events remain unchanged.</p><label>Inventory record ID<input v-model="selected" :disabled="busy" /></label><label>Expected case version<input v-model="expected" type="number" min="1" :disabled="busy" /></label><label>Corrected narrative<textarea v-model="narrative" maxlength="60000" :disabled="busy" /></label><label>Correction reason<textarea v-model="reason" maxlength="1000" :disabled="busy" /></label><button :disabled="busy || !request || !selected || !narrative || !reason" @click="execute('correct', {record_id: selected, patch: {expected_version: Number(expected), narrative, reason}})">Apply authorized correction</button></section>
 <section><h2>Actual inventory</h2><p v-if="!rows.length">No currently accessible registered objects loaded.</p><div class="scroll"><table v-if="rows.length"><thead><tr><th>Record / lineage</th><th>Source</th><th>Subject</th><th>Generation</th></tr></thead><tbody><tr v-for="r in rows" :key="r.ID"><td><button @click="selected = r.ID">{{ r.ID }}</button><br />{{ r.LineageID }}</td><td>{{ r.Source }}</td><td>{{ r.SubjectID }}</td><td>{{ r.Generation }}</td></tr></tbody></table></div></section>
 <section><h2>Durable deletion journal</h2><p v-if="!entries.length">No request journal loaded.</p><div class="scroll"><table v-if="entries.length"><thead><tr><th>Record</th><th>State</th><th>Generation</th><th>Version</th></tr></thead><tbody><tr v-for="e in entries" :key="e.ID"><td>{{ e.RecordID }}</td><td>{{ e.State }}</td><td>{{ e.Generation }}</td><td>{{ e.Version }}</td></tr></tbody></table></div></section>
 </main>
</template>
<style scoped>
.governance-page{max-width:1100px;margin:auto;padding:2rem}h1{font-size:1.75rem;font-weight:650}h2{font-size:1.2rem;font-weight:600}section{margin-top:1.5rem;padding:1.25rem;border:1px solid hsl(var(--border));border-radius:.5rem}p{margin:.7rem 0;color:hsl(var(--muted-foreground))}label{display:block;margin:.7rem 0}input,select,textarea,button{border:1px solid hsl(var(--border));padding:.5rem;border-radius:.25rem;background:hsl(var(--background));margin:.2rem}textarea{display:block;min-height:6rem;width:100%}button:disabled{opacity:.45}.error{color:#b91c1c}.policy-note{border-left:3px solid #b45309;padding-left:1rem}.scroll{overflow:auto}table{width:100%;text-align:left}td,th{padding:.6rem;border-bottom:1px solid hsl(var(--border));overflow-wrap:anywhere}@media(max-width:650px){.governance-page{padding:1rem}input{max-width:100%}}
</style>
